func DoNoDeadlock() {
    log.Println("DoNoDeadlock invoked")
}

func DoDeadlock() {
    log.Println("DoDeadlock invoked")
    ch := make(chan struct{})
    <-ch // blocks forever
}

func TestAllGoRoutinesFinished(t *testing.T) {
    var wg sync.WaitGroup
    wg.Go(DoNoDeadlock)
    wg.Go(DoDeadlock)
    wg.Wait()
}

func TestAllGoRoutinesFinishedSynctest(t *testing.T) {
    synctest.Test(t, func(t *testing.T) {
        go DoNoDeadlock()
        go DoNoDeadlock()
    })
}

